pragma solidity 0.8.36;
interface GetterBase { function value() external view returns (uint256); }
contract GetterImpl is GetterBase { uint256 public override value = 7; function read() external view returns (uint256) { return value; } }
contract Root { function f() public pure virtual returns (uint256) { return 1; } }
contract Left is Root { function f() public pure virtual override returns (uint256) { return super.f() + 10; } }
contract Right is Root { function f() public pure virtual override returns (uint256) { return super.f() + 100; } }
contract Diamond is Left, Right { function f() public pure override(Left, Right) returns (uint256) { return super.f() + 1000; } }
